/// Returns a new vector equal to `a` followed by `b`.
///
/// Correctness argument (informal but complete):
/// - Let `la = a.len()` and `lb = b.len()`.
/// - We allocate `c` with capacity `la + lb`, then push each element of `a` in order,
///   then push each element of `b` in order.
/// - After the first loop, `c.len() == la` and for every `i < la`, `c[i] == a[i]`.
///   (Reason: each `a[i]` is pushed exactly once, in increasing index order.)
/// - After the second loop, `c.len() == la + lb` and for every `i < lb`,
///   `c[la + i] == b[i]`.
///   (Reason: elements of `b` are appended after all `a` elements.)
/// - Thus:
///   * `c.len() == a.len() + b.len()`
///   * `c[i] == a[i]` for all valid `i` in `a`
///   * `c[a.len() + i] == b[i]` for all valid `i` in `b`
///
/// Termination:
/// - Both loops iterate over finite vectors (`a` and `b`) and perform a constant
///   amount of work per element, so the function always terminates.
pub fn append_array(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    let mut c = Vec::with_capacity(a.len() + b.len());

    for x in a {
        c.push(x);
    }
    for x in b {
        c.push(x);
    }

    c
}

